from typing import List
from math import gcd

def canTraverseAllPairs(nums: List[int]) -> bool:
    if len(nums) == 1:
        return True

    nums = set(nums)

    if 1 in nums:
        return False

    if len(nums) == 1:
        return True

    nums = sorted(nums, reverse=True)
    i = 0

    while i < len(nums) - 1:
        result = True
        j = i + 1

        while j < len(nums):
            if gcd(nums[i], nums[j]) > 1:
                nums[i] *= nums[j]
                break
            j += 1

        if j == len(nums):
            return False

        i += 1

    return True
